// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(uint256 pick) public {
        // Interface ids recomputed from their selectors (XOR), as ERC-165 defines them.
        bytes4 iacId =
            bytes4(keccak256("hasRole(bytes32,address)")) ^
            bytes4(keccak256("getRoleAdmin(bytes32)")) ^
            bytes4(keccak256("grantRole(bytes32,address)")) ^
            bytes4(keccak256("revokeRole(bytes32,address)")) ^
            bytes4(keccak256("renounceRole(bytes32,address)"));
        bytes4 e165Id = bytes4(keccak256("supportsInterface(bytes4)"));

        // Wide fuzz-driven id choice: branch into each advertised interface id,
        // otherwise use an arbitrary fuzzed selector.
        bytes4 id;
        uint256 branch = pick % 3;
        if (branch == 0) {
            id = iacId;
        } else if (branch == 1) {
            id = e165Id;
        } else {
            id = bytes4(uint32(uint256(keccak256(abi.encodePacked(pick)))));
        }

        bool isAdvertised = (id == iacId || id == e165Id);
        bool res = c.supportsInterface(id);

        // Universal rule: c must report support for every interface it implements
        // (IAccessControl and IERC165). The mutant's AND returns false whenever the
        // id is the IAccessControl interface id (it can never equal the IERC165 id
        // simultaneously), so this assertion fails there.
        assertTrue(!isAdvertised || res, "implemented interfaces must be reported as supported");
    }
}
